
import math
import tkinter as tk
from tkinter import ttk
#k =1
root = tk.Tk()
root.title("Sorens Rock SI")
root.geometry("400x300")
class Rock:
    
    def __init__(self, id, color=None, composition=None):
        self.id = id
        self.color = color
        self.composition = composition if composition is not None else {}

# Training Data this data was generated by ai
training_data = [
    Rock(id=1, color="Pink", composition={"Quartz": 75, "Feldspar": 15, "Mafic": 10}),
    Rock(id=2, color="Pink", composition={"Quartz": 68, "Feldspar": 22, "Mafic": 10}),
    Rock(id=3, color="Gray", composition={"Quartz": 35, "Feldspar": 50, "Mafic": 15}),
    Rock(id=4, color="Gray", composition={"Quartz": 40, "Feldspar": 45, "Mafic": 15}),
    Rock(id=5, color="Gray", composition={"Quartz": 40, "Feldspar": 45, "Mafic": 15}),
    Rock(id=6, color="Black", composition={"Quartz": 5, "Feldspar": 55, "Mafic": 40}),
    Rock(id=7, color="Black", composition={"Quartz": 0, "Feldspar": 15, "Mafic": 85}),
    #Rock(id=8, color="Black", composition={"Quartz": 2, "Feldspar": 8, "Mafic": 90}),
]



def predict_color(unkown_rock):
    mineral_components=["Quartz","Feldspar","Mafic"]
    closest_rock = None
    shortest_distance = float('inf')
    for rock in training_data:
        squared_diff_sum = 0
        for mineral in mineral_components:
            value1= unkown_rock.composition.get(mineral,0)
            value2 = rock.composition.get(mineral,0)
            squared_diff_sum +=(value1-value2)**2
        distance = math.sqrt(squared_diff_sum)


        if distance <shortest_distance:
            shortest_distance =distance
            closest_rock = rock
    print(f"Rock 9 has a color of {closest_rock}")
    return  closest_rock.color 

            #d=sqrt((x2-x1)^2+(y2-y1)^2+(z2-z1)^2)

       
       





unkown_rock = Rock(id=9,color=None, composition={"Quartz": 2, "Feldspar":8, "Mafic": 90})
predicted_color = predict_color(unkown_rock)

print(f"Rock 9 has a color of {predicted_color}")
label = ttk.Label(root, text=f"The Color of the rock is {predicted_color}")
label.pack(pady=20)

root.mainloop()